CREATE TABLE IF NOT EXISTS portal_state (id INTEGER PRIMARY KEY CHECK (id = 1), revision BIGINT NOT NULL DEFAULT 0, data JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS portal_audit (id BIGSERIAL PRIMARY KEY, occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), actor TEXT NOT NULL, old_revision BIGINT, new_revision BIGINT, operation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id UUID PRIMARY KEY, name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL, storage_path TEXT NOT NULL, uploaded_by TEXT NOT NULL, uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
